package edu.pe.cibertec.saibm.inventario.domain.model; import edu.pe.cibertec.saibm.inventario.domain.exception.InventoryConflictException; public final class Stock {private final String bookId; private int totalStock,availableStock; public Stock(String b,int t,int a){if(b==null||b.isBlank()||t<0||a<0||a>t)throw new InventoryConflictException("Invalid stock");bookId=b;totalStock=t;availableStock=a;} public String bookId(){return bookId;} public int totalStock(){return totalStock;} public int availableStock(){return availableStock;} public int getTotalStock(){return totalStock;} public int getAvailableStock(){return availableStock;} public boolean reserve(int q){if(q<1||availableStock<q)return false;availableStock-=q;return true;} public void release(int q){if(q<1)throw new InventoryConflictException("Invalid quantity");availableStock=Math.min(totalStock,availableStock+q);} public void adjustTotal(int t){int reserved=totalStock-availableStock;if(t<reserved)throw new InventoryConflictException("Total stock cannot be lower than reserved stock");totalStock=t;availableStock=t-reserved;}}
